import * as pulumi from "@pulumi/pulumi";
import * as gcp from "@pulumi/gcp";
import { enableService } from "./services";

const config = new pulumi.Config();

// Domains the platform serves from. Safe (example) defaults live here; the real production domains
// are set per-stack in Pulumi.prod.yaml, so a non-prod stack never touches real DNS.
//   externalDomain — public-facing website
//   internalDomain — admin / staff / volunteer portals
//   shortDomain    — link shortener
const externalDomain = config.get("externalDomain") ?? "external.example.com";
export const internalDomain = config.get("internalDomain") ?? "internal.example.com";
const shortDomain = config.get("shortDomain") ?? "short.example.com";

const dnsApi = enableService("dns.googleapis.com");

/**
 * A public Cloud DNS managed zone for a domain. Creating the zone is **inert** — nothing resolves
 * through it until the domain's registrar delegates to this zone's name servers (a manual step,
 * and for the existing external domain, only after its current records are migrated in). Records
 * are added in the slices that stand up the services they point at.
 */
export class ManagedZone extends gcp.dns.ManagedZone {
  constructor(name: string, domain: pulumi.Input<string>, opts?: pulumi.CustomResourceOptions) {
    super(
      name,
      {
        // Cloud DNS requires the fully-qualified name with a trailing dot.
        dnsName: pulumi.interpolate`${domain}.`,
        description: pulumi.interpolate`DNS zone for ${domain}`,
        visibility: "public",
      },
      { dependsOn: dnsApi, ...opts },
    );
  }
}

// One managed zone per platform domain. Their name servers are exported so the registrar
// delegation (the human step) can be looked up after apply.
export const externalZone = new ManagedZone("external", externalDomain);
export const internalZone = new ManagedZone("internal", internalDomain);
export const shortZone = new ManagedZone("short", shortDomain);

export const nameServers = {
  external: externalZone.nameServers,
  internal: internalZone.nameServers,
  short: shortZone.nameServers,
};
---config---
import * as gcp from "@pulumi/gcp";

// Cross-cutting values used across the package. Configuration used by only one file lives in that
// file (e.g. domains in dns.ts, the VM machine type in compute.ts).

export const location = gcp.config.region ?? "us-west1";

// Safe (non-prod) default. The production project is set per-stack via `gcp:project` in
// Pulumi.prod.yaml, so a stack that forgets to configure it fails safely instead of silently
// targeting production.
export const projectId = gcp.config.project ?? "cyc-admin-scripts-dev";

// Users who are allowed to deploy this app.
export const deployers = ["user:master@cyccommunitysailing.org", "user:ungood@onetrue.name"];
---readme portal---
# @cyc-seattle/portal

The `cycsail.team` link portal: a **purely static site** (no backend) that gives staff, volunteers,
and instructors one bookmark for the tools they use. It doubles as the platform's **Google-auth
proof-of-concept** — the same Caddy + oauth2-proxy pattern that will later front apps like FreeScout.

## How it works

- **Content:** `src/links.ts` is the single source of truth — a typed, audience-grouped list of
  links. `pnpm --filter @cyc-seattle/portal build` renders it to `dist/site/index.html`.
- **Serving + auth:** Caddy (this package's `Dockerfile`) serves the static files and gates every
  request through **oauth2-proxy** (Google). oauth2-proxy accepts **any Google account** but is
  restricted to members of **`all@cyccommunitysailing.org`** (which nests `staff@`, `volunteers@`,
  …). Reaching the site at all _is_ the access check — there is no per-page logic. Volunteers on
  personal Google accounts get in by being group members.
- **Where it runs:** the substrate VM, as a two-container compose stack defined by
  `deploy/docker-compose.yml` and `deploy/Caddyfile`. The VM boots it via cloud-init — see
  `infrastructure/src/portal-bootstrap.ts`.

## What Pulumi manages (`infrastructure/src/portal.ts` + `portal-bootstrap.ts`)

- The Caddy image (static site baked in) in Artifact Registry.
- Secret Manager secrets `portal-oauth-client-id`, `portal-oauth-client-secret`,
  `portal-oauth-cookie-secret` (declared here; values set out of band).
- The substrate VM's `user-data` cloud-init, which fetches those secrets at boot and runs the
  compose stack.
- An `A` record for `cycsail.team` → the substrate VM's static IP.

So a `just deploy` builds/pushes the image and (re)configures the VM. **Because cloud-init only runs
on first boot, an already-running VM must be reset (or the bootstrap re-run by hand) to pick up a
new stack.**

## One-time manual prerequisites

The portal needs a few out-of-band steps (OAuth client + External consent screen, domain-wide
delegation, the `all@` group, and DNS delegation) before it serves. These can't be
infrastructure-as-code, so they live in the repo-wide record: **[docs/manual-setup.md](../../docs/manual-setup.md) → §4 (DNS) and §5 (Portal Google auth)**.

## Config knobs (Pulumi)

- `infrastructure:portalAuthGroup` (default `all@cyccommunitysailing.org`)
- `infrastructure:portalAuthAdminEmail` (default `master@cyccommunitysailing.org`)

