// Validates the exact request shapes used by DirectusRole's create/update/delete against a live
// instance (mirrors packages/infrastructure/src/directus.ts's provider logic).
const baseUrl = "http://localhost:8097";
const adminEmail = "admin@example.com";
const adminPassword = "throwaway-admin-pw";

async function login(baseUrl, email, password) {
  const res = await fetch(`${baseUrl}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  if (!res.ok) throw new Error(`login failed: ${res.status} ${await res.text()}`);
  return (await res.json()).data.access_token;
}

async function req(baseUrl, token, method, path, body) {
  const res = await fetch(`${baseUrl}${path}`, {
    method,
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) throw new Error(`${method} ${path} -> ${res.status}: ${await res.text()}`);
  return res.status === 204 ? undefined : res.json();
}

async function grantPermission(baseUrl, token, policyId, rule) {
  await req(baseUrl, token, "POST", "/permissions", {
    policy: policyId,
    collection: rule.collection,
    action: rule.action,
    permissions: rule.permissions ?? {},
    fields: rule.fields ?? ["*"],
  });
}

async function clearPermissions(baseUrl, token, policyId) {
  const existing = await req(baseUrl, token, "GET", `/permissions?filter[policy][_eq]=${policyId}&limit=-1`);
  for (const permission of existing.data) {
    await req(baseUrl, token, "DELETE", `/permissions/${permission.id}`);
  }
}

async function create(inputs) {
  const token = await login(inputs.baseUrl, inputs.adminEmail, inputs.adminPassword);
  const policy = await req(inputs.baseUrl, token, "POST", "/policies", {
    name: inputs.name,
    icon: inputs.icon,
