1	import * as pulumi from "@pulumi/pulumi";
2	import * as gcp from "@pulumi/gcp";
3	import { postgres } from "./database";
4	import { address, substrateRunner } from "./compute";
5	import { internalDomain, internalZone } from "./dns";
6	import { Secret } from "./secret";
7	import { enableService } from "./services";
8	
9	// Directus itself: the substrate for the people hub (and any future app that wants a
10	// relationship-based permission engine — see docs/architecture.md). Runs on the substrate VM
11	// against its own database on the shared Cloud SQL instance. One database for the whole instance,
12	// not one per app — Directus's own collections are how data is organized within it.
13	//
14	// App-specific schema/roles (e.g. the people hub's) live in that app's own file — see
15	// people-hub.ts — built on the DirectusRole resource this file exports.
16	
17	const secretmanagerApi = enableService("secretmanager.googleapis.com");
18	
19	export const directusDatabase = postgres.database("directus");
20	
21	// Directus's own secrets. The Google OAuth client is shared platform-wide (substrate.ts), not
22	// declared here — signing in once should sign into every surface on the substrate, not just this
23	// one. Values set out of band, same pattern as portal.ts.
24	const secrets = {
25	  // Directus's own encryption/signing secrets (its `KEY`/`SECRET` env vars).
26	  "directus-key": new Secret("directus-key", { dependsOn: secretmanagerApi }),
27	  "directus-secret": new Secret("directus-secret", { dependsOn: secretmanagerApi }),
28	  "directus-db-password": new Secret("directus-db-password", { dependsOn: secretmanagerApi }),
29	  // First-boot admin account password; rotate and stop using once real staff users exist. Also
30	  // what the DirectusRole dynamic resources below authenticate with to create roles/policies.
31	  "directus-admin-bootstrap-password": new Secret("directus-admin-bootstrap-password", {
32	    dependsOn: secretmanagerApi,
33	  }),
34	  // Directus 12+ (MSCL-licensed) gates custom/relational permission rules — exactly what the
35	  // Guardian role below needs — behind a license. CYC has one via Directus's Open Innovation
36	  // Grant; see docs/manual-setup.md §6. Optional at the Pulumi level (Directus runs on the Core
37	  // tier if empty), but required for the Guardian role to actually work.
38	  "directus-license-key": new Secret("directus-license-key", { dependsOn: secretmanagerApi }),
39	};
40	
41	for (const secret of Object.values(secrets)) {
42	  secret.grant(substrateRunner.member);
43	}
44	
45	// Point crm.<internalDomain> at the substrate VM, same pattern as portal.ts's own record.
46	export const directusDnsRecord = new gcp.dns.RecordSet("directus-a", {
47	  name: pulumi.interpolate`crm.${internalDomain}.`,
48	  type: "A",
49	  ttl: 300,
50	  managedZone: internalZone.name,
51	  rrdatas: [address.address],
52	});
53	
54	// --- DirectusRole: a Pulumi dynamic resource managing a Directus role + its policy + permission
55	// rules as one unit, via Directus's REST API. Reusable across any Directus-backed app; app-specific
56	// instances (Staff/Coach/Guardian, say) live in that app's own file (see people-hub.ts).
57	//
58	// This is the first dynamic resource in this repo, and the first place Pulumi authenticates to an
59	// application's own API rather than just GCP's — worth reading closely before extending it.
60	
61	export interface DirectusPermissionRule {
62	  collection: string;
63	  action: "create" | "read" | "update" | "delete";
64	  /** A Directus permission filter (row-level rule), e.g. a $CURRENT_USER-scoped relational filter.
65	   * Omit for unrestricted access to the allowed fields. Requires a license on Directus 12+. */
66	  permissions?: Record<string, unknown>;
67	  /** Defaults to every field. */
68	  fields?: string[];
69	}
70	
71	interface DirectusRoleInputs {
72	  baseUrl: string;
73	  adminEmail: string;
74	  adminPassword: string;
75	  name: string;
76	  icon?: string;
77	  description?: string;
78	  permissionRules: DirectusPermissionRule[];
79	}
80	
81	interface DirectusRoleOutputs extends DirectusRoleInputs {
82	  roleId: string;
83	  policyId: string;
84	}
85	
86	// This package's tsconfig (@tsconfig/node20, lib: es2023, no DOM) hits an @types/node quirk where
87	// the ambient `fetch`/`Response` types resolve to an empty structural type rather than undici's
88	// real one (its conditional type meant to defer to DOM lib's Response misfires with no DOM lib
89	// present either). Rather than cast at every call site, wrap `fetch` once with the shape we
90	// actually use.
91	interface HttpResponse {
92	  readonly ok: boolean;
93	  readonly status: number;
94	  text(): Promise<string>;
95	  json(): Promise<unknown>;
96	}
97	
98	async function httpFetch(input: string, init?: RequestInit): Promise<HttpResponse> {
99	  return (await fetch(input, init)) as unknown as HttpResponse;
100	}
101	
102	async function waitForReachable(baseUrl: string, timeoutMs = 180_000): Promise<void> {
103	  const start = Date.now();
104	  let lastError: unknown;
105	  while (Date.now() - start < timeoutMs) {
106	    try {
107	      const res = await httpFetch(`${baseUrl}/server/ping`);
108	      if (res.ok) return;
109	    } catch (error) {
110	      lastError = error;
111	    }
112	    await new Promise((resolve) => setTimeout(resolve, 5_000));
113	  }
114	  throw new Error(
115	    `Directus at ${baseUrl} did not become reachable within ${timeoutMs}ms (VM boot/DNS/TLS may still be in ` +
116	      `progress — re-run \`pulumi up\` once it's up). Last error: ${String(lastError)}`,
117	  );
118	}
119	
120	async function login(baseUrl: string, email: string, password: string): Promise<string> {
121	  const res = await httpFetch(`${baseUrl}/auth/login`, {
122	    method: "POST",
123	    headers: { "Content-Type": "application/json" },
124	    body: JSON.stringify({ email, password }),
125	  });
126	  if (!res.ok) {
127	    throw new Error(`Directus login as ${email} failed: ${res.status} ${await res.text()}`);
128	  }
129	  return ((await res.json()) as { data: { access_token: string } }).data.access_token;
130	}
131	
132	async function directusRequest<T>(
133	  baseUrl: string,
134	  token: string,
135	  method: string,
136	  path: string,
137	  body?: unknown,
138	): Promise<T> {
139	  const res = await httpFetch(`${baseUrl}${path}`, {
140	    method,
141	    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
142	    body: body !== undefined ? JSON.stringify(body) : undefined,
143	  });
144	  if (!res.ok) {
145	    throw new Error(`${method} ${path} -> ${res.status}: ${await res.text()}`);
146	  }
147	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
148	}
149	
150	async function grantPermission(
151	  baseUrl: string,
152	  token: string,
153	  policyId: string,
