  policyId: string;
}

async function grantPermission(
  baseUrl: string,
  token: string,
  policyId: string,
  rule: DirectusPermissionRule,
): Promise<void> {
  await directusRequest(baseUrl, token, "POST", "/permissions", {
    policy: policyId,
    collection: rule.collection,
    action: rule.action,
    permissions: rule.permissions ?? {},
    fields: rule.fields ?? ["*"],
  });
}

