16	// exports.
17	
18	const secretmanagerApi = enableService("secretmanager.googleapis.com");
19	
20	export const directusDatabase = postgres.database("directus");
21	
22	// Directus's own secrets. The Google OAuth client is shared platform-wide (substrate.ts), not
23	// declared here — signing in once should sign into every surface on the substrate, not just this
24	// one.
25	//
26	// The internal ones (key/secret/db password/bootstrap password) have no meaningful human choice,
27	// so Pulumi generates and manages their values directly (randomSecret) — nothing to set out of
28	// band. `directus-license-key` stays a plain Secret: it's an external credential (the Open
29	// Innovation Grant / a paid license), same "container only, value out of band" pattern as
30	// `google-oauth-client-id`/`-secret` in substrate.ts.
31	const directusKey = randomSecret("directus-key", { dependsOn: secretmanagerApi });
32	const directusSecret = randomSecret("directus-secret", { dependsOn: secretmanagerApi });
33	const directusDbPassword = randomSecret("directus-db-password", { dependsOn: secretmanagerApi });
